import{_ as s,C as n,o as t,c as i,a2 as o,b as d,w as r,a as l,E as h,a3 as c}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"What Ershu is","description":"Learn how Ershu turns several repositories into project knowledge for the web app and AI coding tools.","frontmatter":{"page_id":"overview-what-is-ershu","title":"What Ershu is","description":"Learn how Ershu turns several repositories into project knowledge for the web app and AI coding tools."},"headers":[],"relativePath":"en/overview/what-is-ershu.md","filePath":"en/overview/what-is-ershu.md","lastUpdated":1786627803000}'),u={name:"en/overview/what-is-ershu.md"};function p(m,e,f,w,g,b){const a=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=o('<h1 id="what-ershu-is" tabindex="-1">What Ershu is <a class="header-anchor" href="#what-ershu-is" aria-label="Permalink to &quot;What Ershu is&quot;">​</a></h1><p>Ershu is self-hosted code-understanding software. Put the frontend, backend, services, and shared libraries for one product into an Ershu project. It reads those repositories and builds an internal wiki, code indexes, project relationships, and interface contracts.</p><p>People use the web app to read, search, and explore relationships. Coding agents query the same results through MCP. MCP is a common protocol for exposing tools to AI clients. Ershu&#39;s MCP tools are read-only and do not modify repositories.</p><h2 id="how-it-differs-from-common-alternatives" tabindex="-1">How it differs from common alternatives <a class="header-anchor" href="#how-it-differs-from-common-alternatives" aria-label="Permalink to &quot;How it differs from common alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Approach</th><th>What it does well</th><th>What it often lacks</th></tr></thead><tbody><tr><td>A hand-written wiki</td><td>Records background, decisions, and team experience</td><td>Needs steady maintenance and can drift away from the current commit</td></tr><tr><td>Repository search</td><td>Finds known symbols and text quickly</td><td>Rarely provides a cross-repository view of the product</td></tr><tr><td>Letting AI scan a workspace</td><td>Reads code for the task at hand</td><td>May rebuild context in every session and is limited to the current workspace</td></tr><tr><td>Ershu</td><td>Stores project-level analysis that the web app and MCP clients can reuse</td><td>Still needs deployment, model configuration, and a first full analysis</td></tr></tbody></table><p>These approaches can work together. Hand-written documentation is useful for explaining why a decision was made. Ershu is better suited to rebuilding what the code says now. Source and tests remain the final authority for exact behavior.</p><h2 id="what-a-full-analysis-produces" tabindex="-1">What a full analysis produces <a class="header-anchor" href="#what-a-full-analysis-produces" aria-label="Permalink to &quot;What a full analysis produces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Result</th><th>What you can do with it</th></tr></thead><tbody><tr><td>Project wiki</td><td>Read modules, workflows, settings, and repository notes by topic, then follow citations to source</td></tr><tr><td>Repository tree and code index</td><td>Browse paths, languages, and symbols without cloning every repository to every reader&#39;s machine</td></tr><tr><td>Keyword and vector indexes</td><td>Search code, documents, interfaces, and configuration by exact term or meaning</td></tr><tr><td>Project knowledge graph</td><td>Explore candidate relationships between repositories, directories, symbols, calls, and dependencies</td></tr><tr><td>Interface contracts</td><td>Query public interfaces, consumer relationships, schemas, and changes between recorded versions</td></tr><tr><td>Run records</td><td>Inspect stages, warnings, model usage, generated results, and the point of failure</td></tr></tbody></table><p>Models participate in document generation. Repository trees, code indexes, interface facts, and some relationships come from deterministic analysis. Results retain commit, freshness, authority, coverage, and truncation signals so clients can tell what is ready to use and what still needs source verification.</p><h2 id="how-the-five-components-work-together" tabindex="-1">How the five components work together <a class="header-anchor" href="#how-the-five-components-work-together" aria-label="Permalink to &quot;How the five components work together&quot;">​</a></h2>',10)),(t(),d(c,null,{default:r(()=>[h(a,{id:"mermaid-147",class:"ershu-mermaid",graph:"flowchart%20LR%0A%20%20Browser%5B%22Browser%22%5D%20--%3E%20Frontend%5B%22Frontend%22%5D%0A%20%20Frontend%20--%3E%20API%5B%22API%22%5D%0A%20%20Agent%5B%22Coding%20agent%22%5D%20--%3E%20MCP%5B%22MCP%22%5D%0A%20%20API%20--%3E%20Core%5B%22Core%22%5D%0A%20%20MCP%20--%3E%20Core%0A%20%20Worker%5B%22Worker%22%5D%20--%3E%20Core%0A%20%20API%20--%3E%20Queue%5B(%22PostgreSQL%20task%20queue%22)%5D%0A%20%20Queue%20--%3E%20Worker%0A%20%20Worker%20--%3E%20Repos%5B%22Read-only%20repository%20workspaces%22%5D%0A%20%20Worker%20--%3E%20Knowledge%5B(%22Documents%2C%20indexes%2C%20and%20relationships%22)%5D%0A%20%20Core%20--%3E%20Knowledge%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<ul><li><strong>Core</strong> owns shared data, permissions, run state, query services, and database migrations. It is a library, not a separate server.</li><li><strong>API</strong> provides sign-in, project management, runs, documents, search, chat, and administration for the web app.</li><li><strong>Worker</strong> claims jobs, reads repositories, and builds documents, indexes, relationships, and interface facts.</li><li><strong>MCP</strong> exposes stored project knowledge to AI clients.</li><li><strong>Frontend</strong> is the browser workspace for the team.</li></ul><p>PostgreSQL stores users, projects, permissions, runs, and documents. Milvus stores vector indexes. Redis handles login throttling and poller coordination; it is not the Worker&#39;s durable task queue.</p><h2 id="choose-only-the-python-components-you-need" tabindex="-1">Choose only the Python components you need <a class="header-anchor" href="#choose-only-the-python-components-you-need" aria-label="Permalink to &quot;Choose only the Python components you need&quot;">​</a></h2><p>The <code>ershu</code> package is the common installation entry point. It installs Core by default, with optional extras for each process:</p><table tabindex="0"><thead><tr><th>Command</th><th>Installs</th></tr></thead><tbody><tr><td><code>pip install ershu</code></td><td>Core and the <code>ershu-db</code> migration command</td></tr><tr><td><code>pip install &quot;ershu[api]&quot;</code></td><td>Core and API</td></tr><tr><td><code>pip install &quot;ershu[mcp]&quot;</code></td><td>Core and MCP</td></tr><tr><td><code>pip install &quot;ershu[worker]&quot;</code></td><td>Core and Worker</td></tr><tr><td><code>pip install &quot;ershu[all]&quot;</code></td><td>Core, API, MCP, and Worker</td></tr></tbody></table><p>A UV project can use <code>uv add ershu</code> or <code>uv add &quot;ershu[all]&quot;</code>. A complete deployment also needs PostgreSQL, Redis, Milvus, supporting infrastructure, and the separately released frontend. For a first deployment, use the deployment archive from an <code>ershu</code> Release.</p><h2 id="from-source-to-a-usable-project-view" tabindex="-1">From source to a usable project view <a class="header-anchor" href="#from-source-to-a-usable-project-view" aria-label="Permalink to &quot;From source to a usable project view&quot;">​</a></h2><ol><li>An administrator creates the first account and configures language-model and embedding channels.</li><li>A project owner creates a project and adds the repositories that ship one product.</li><li>The first run covers every active repository and establishes the project baseline.</li><li>The Worker reads source and stores the wiki, indexes, relationships, contracts, and run record.</li><li>The team uses those results in the web app, while AI clients retrieve them through MCP.</li><li>New runs, scheduled polling, or signed webhooks refresh project facts after the code changes.</li></ol><p>An automated fact refresh does not regenerate model-written documents. Start a document-producing analysis when the wiki needs to be updated.</p><h2 id="boundaries-to-know-first" tabindex="-1">Boundaries to know first <a class="header-anchor" href="#boundaries-to-know-first" aria-label="Permalink to &quot;Boundaries to know first&quot;">​</a></h2><ul><li>API can queue a run without a Worker, but the run will not finish.</li><li>Semantic search needs Milvus, a working embedding channel, and a completed vector index. Keyword search does not need an embedding model.</li><li>Relationships, change surfaces, and static runtime paths narrow the search area. They are not proof of every dynamic call.</li><li>A local repository path must be visible to the hosts running API, Worker, or MCP and must fall under an allowed root.</li><li>Self-hosting gives the operator control over services and storage. Whether model traffic stays on a private network depends on the configured model channels.</li></ul><p>See <a href="./use-cases">use cases</a> for what different roles can do with Ershu. To try it, start with the <a href="/en/guide/quick-start">one-machine deployment</a>.</p>',12))])}const v=s(u,[["render",p]]);export{k as __pageData,v as default};
